def topo_sort(graph):
    nodes = set(graph.keys()) | {n for deps in graph.values() for n in deps}
    in_degree = {n: 0 for n in nodes}
    for u, deps in graph.items():
        for v in deps:
            in_degree[u] += 1
    ready = sorted([n for n in nodes if in_degree[n] == 0])
    result = []
    while ready:
        u = ready.pop(0)
        result.append(u)
        for v in graph.get(u, []):
            in_degree[v] -= 1
            if in_degree[v] == 0:
                ready.append(v)
        ready.sort()
    if len(result) != len(nodes):
        raise ValueError("Cycle detected")
    return result
