def window_sums(nums, k):
    if k <= 0:
        raise ValueError("k must be positive")
    if k > len(nums):
        return []

    result = []
    current_sum = 0
    for i, num in enumerate(nums):
        current_sum += num
        if i >= k - 1:
            result.append(current_sum)
            current_sum -= nums[i - k + 1]

    return result
