import ipaddress

def is_private_ipv4(text):
    try:
        addr = ipaddress.ip_address(text)
        if not isinstance(addr, ipaddress.IPv4Address):
            return False
        if not ipaddress.is_private(addr):
            return False
        return True
    except ValueError:
        return False
